// Makes bare URLs in the bibliography generated by @quartz-community/citations
// clickable. citeproc emits URLs as plain text, and Quartz's normal link
// handling runs at the Markdown stage, before this HTML exists. Runs after the
// citations transformer (order 85; this plugin is 87).
//
// `dist/` is committed as the plugin source; there is no build step.

const URL_RE = /https?:\/\/[^\s<>"']+/g
const TRAILING_PUNCTUATION = /[.,;:!?]+$/

// Tags whose text must not be rewritten: existing links, code, and raw HTML.
const SKIP_TAGS = new Set(["a", "code", "pre", "script", "style"])

const linkifyText = (value) => {
  const nodes = []
  let last = 0

  URL_RE.lastIndex = 0
  let match
  while ((match = URL_RE.exec(value)) !== null) {
    let url = match[0]
    // Leave sentence punctuation outside the anchor.
    const trailing = url.match(TRAILING_PUNCTUATION)
    if (trailing) url = url.slice(0, -trailing[0].length)
    if (!url) continue

    if (match.index > last) {
      nodes.push({ type: "text", value: value.slice(last, match.index) })
    }
    nodes.push({
      type: "element",
      tagName: "a",
      properties: { href: url },
      children: [{ type: "text", value: url }],
    })
    last = match.index + url.length
  }

  if (last < value.length) {
    nodes.push({ type: "text", value: value.slice(last) })
  }
  return nodes
}

const linkify = (node) => {
  if (!node || !Array.isArray(node.children)) return

  const children = []
  for (const child of node.children) {
    if (child.type === "text") {
      children.push(...linkifyText(child.value))
    } else if (child.type === "element" && !SKIP_TAGS.has(child.tagName)) {
      linkify(child)
      children.push(child)
    } else {
      children.push(child)
    }
  }
  node.children = children
}

const findRefs = (node) => {
  if (!node || !Array.isArray(node.children)) return null
  for (const child of node.children) {
    if (
      child.type === "element" &&
      child.tagName === "div" &&
      child.properties?.id === "refs"
    ) {
      return child
    }
    const found = findRefs(child)
    if (found) return found
  }
  return null
}

const BibliographyLinks = () => ({
  name: "BibliographyLinks",
  htmlPlugins() {
    return [
      () => (tree) => {
        const refs = findRefs(tree)
        if (refs) linkify(refs)
      },
    ]
  },
})

export default BibliographyLinks
